package com.acme.gateway

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model.ws.{Message, TextMessage}
import akka.http.scaladsl.server.Directives._
import akka.stream.scaladsl.{Flow, Sink, Source}
import akka.stream.{ActorMaterializer, OverflowStrategy}
import spray.json._
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import scala.collection.concurrent.TrieMap
import scala.util.Try

object WebSocketGateway extends App with DefaultJsonProtocol {

  implicit val system: ActorSystem = ActorSystem("ws-gateway")
  implicit val materializer: ActorMaterializer = ActorMaterializer()

  // Session store: sessionId -> (username, role, namespaceAccess, originalRole, originalNamespaces)
  val sessions = TrieMap.empty[String, (String, String, Set[String], String, Set[String])]

  // HMAC key loaded from K8s secret mount
  val hmacKey: Array[Byte] = sys.env.getOrElse("HMAC_SECRET",
    scala.io.Source.fromFile("/var/run/secrets/gateway/hmac-key").mkString
  ).getBytes("UTF-8")

  case class AuthPayload(sub: String, role: String, namespaces: List[String], iat: Long, exp: Long)
  implicit val authPayloadFormat: RootJsonFormat[AuthPayload] = jsonFormat5(AuthPayload)

  def verifyToken(token: String): Option[AuthPayload] = {
    val parts = token.split("\\.")
    if (parts.length != 3) return None
    val headerB64 = parts(0)
    val payloadB64 = parts(1)
    val signatureB64 = parts(2)

    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacKey, "HmacSHA256"))
    val expectedSig = Base64.getUrlEncoder.withoutPadding.encodeToString(
      mac.doFinal(s"$headerB64.$payloadB64".getBytes("UTF-8"))
    )

    // Constant-time comparison for signature
    if (!java.security.MessageDigest.isEqual(expectedSig.getBytes, signatureB64.getBytes)) return None

    val payloadJson = new String(Base64.getUrlDecoder.decode(payloadB64), "UTF-8")
    val payload = Try(payloadJson.parseJson.convertTo[AuthPayload]).toOption
    payload.filter(p => p.exp > System.currentTimeMillis() / 1000)
  }

  def deriveEffectiveRole(tokenRole: String, requestedNamespace: String, grantedNamespaces: Set[String]): String = {
    // Role hierarchy: cluster-admin > namespace-admin > editor > viewer
    val roleHierarchy = Map("cluster-admin" -> 4, "namespace-admin" -> 3, "editor" -> 2, "viewer" -> 1)
    val roleLevel = roleHierarchy.getOrElse(tokenRole, 0)

    if (roleLevel >= 4) {
      "cluster-admin"
    } else if (grantedNamespaces.contains(requestedNamespace) && roleLevel >= 3) {
      "namespace-admin"
    } else if (grantedNamespaces.contains(requestedNamespace)) {
      tokenRole
    } else {
      "viewer"
    }
  }

  // Process escalation request - allows assuming a service account role within namespace
  def processEscalationRequest(sessionId: String, targetRole: String, namespace: String): String = {
    sessions.get(sessionId) match {
      case Some((username, currentRole, namespaces, originalRole, originalNamespaces)) =>
        // Always check against ORIGINAL token role and namespaces, not current session state
        val effectiveRole = deriveEffectiveRole(originalRole, namespace, originalNamespaces)
        val roleHierarchy = Map("cluster-admin" -> 4, "namespace-admin" -> 3, "editor" -> 2, "viewer" -> 1)
        val currentLevel = roleHierarchy.getOrElse(effectiveRole, 0)
        val targetLevel = roleHierarchy.getOrElse(targetRole, 0)

        // Check: can only escalate to roles at or below current effective level
        if (targetLevel <= currentLevel) {
          // Update session with new role but preserve original credentials
          sessions.update(sessionId, (username, targetRole, namespaces, originalRole, originalNamespaces))
          JsObject(
            "status" -> JsString("granted"),
            "role" -> JsString(targetRole),
            "namespace" -> JsString(namespace)
          ).compactPrint
        } else {
          JsObject(
            "status" -> JsString("denied"),
            "reason" -> JsString("insufficient privileges")
          ).compactPrint
        }
      case None =>
        JsObject(
          "status" -> JsString("error"),
          "reason" -> JsString("invalid session")
        ).compactPrint
    }
  }

  // Process namespace binding - binds additional namespaces to session
  def processNamespaceBinding(sessionId: String, namespace: String): String = {
    sessions.get(sessionId) match {
      case Some((username, role, namespaces, originalRole, originalNamespaces)) =>
        val roleHierarchy = Map("cluster-admin" -> 4, "namespace-admin" -> 3, "editor" -> 2, "viewer" -> 1)
        // Check against original role, not potentially-escalated current role
        val roleLevel = roleHierarchy.getOrElse(originalRole, 0)
        // Only cluster-admin can bind arbitrary namespaces
        // namespace-admin can bind sub-namespaces (prefix match) of their ORIGINAL namespaces
        if (roleLevel >= 4) {
          sessions.update(sessionId, (username, role, namespaces + namespace, originalRole, originalNamespaces))
          JsObject(
            "status" -> JsString("bound"),
            "namespace" -> JsString(namespace)
          ).compactPrint
        } else if (roleLevel >= 3 && originalNamespaces.exists(ns => namespace.startsWith(ns + "-"))) {
          sessions.update(sessionId, (username, role, namespaces + namespace, originalRole, originalNamespaces))
          JsObject(
            "status" -> JsString("bound"),
            "namespace" -> JsString(namespace)
          ).compactPrint
        } else {
          JsObject(
            "status" -> JsString("denied"),
            "reason" -> JsString("cannot bind namespace")
          ).compactPrint
        }
      case None =>
        JsObject(
          "status" -> JsString("error"),
          "reason" -> JsString("invalid session")
        ).compactPrint
    }
  }

  def wsHandler(sessionId: String): Flow[Message, Message, Any] = {
    Flow[Message].collect {
      case TextMessage.Strict(text) =>
        val json = Try(text.parseJson.asJsObject).getOrElse(JsObject.empty)
        val action = json.fields.get("action").collect { case JsString(s) => s }.getOrElse("")
        val response = action match {
          case "escalate" =>
            val targetRole = json.fields.get("role").collect { case JsString(s) => s }.getOrElse("viewer")
            val ns = json.fields.get("namespace").collect { case JsString(s) => s }.getOrElse("default")
            processEscalationRequest(sessionId, targetRole, ns)
          case "bind-namespace" =>
            val ns = json.fields.get("namespace").collect { case JsString(s) => s }.getOrElse("default")
            processNamespaceBinding(sessionId, ns)
          case "whoami" =>
            sessions.get(sessionId).map { case (u, r, ns, _, _) =>
              JsObject(
                "user" -> JsString(u),
                "role" -> JsString(r),
                "namespaces" -> JsArray(ns.toVector.map(JsString(_)))
              ).compactPrint
            }.getOrElse(JsObject("error" -> JsString("no session")).compactPrint)
          case _ => JsObject("error" -> JsString("unknown action")).compactPrint
        }
        TextMessage(response)
    }
  }

  val route = path("ws" / "admin") {
    parameter("token") { token =>
      verifyToken(token) match {
        case Some(payload) =>
          val sessionId = java.util.UUID.randomUUID().toString
          val nsSet = payload.namespaces.toSet
          sessions.put(sessionId, (payload.sub, payload.role, nsSet, payload.role, nsSet))
          handleWebSocketMessages(wsHandler(sessionId))
        case None =>
          reject
      }
    }
  }

  Http().bindAndHandle(route, "0.0.0.0", 8443)
  println("WebSocket Gateway started on :8443")
}
